import{_ as a,o,c as t,a5 as c}from"./chunks/framework.BEZBAInb.js";const u=JSON.parse('{"title":"シーン形式のリソース","description":"","frontmatter":{"title":"シーン形式のリソース","order":8},"headers":[],"relativePath":"ja/latest/tutorial/core/scene-assets.md","filePath":"ja/latest/tutorial/core/scene-assets.md","lastUpdated":1788455378000}'),s={name:"ja/latest/tutorial/core/scene-assets.md"};function r(d,e,n,_,i,p){return o(),t("div",null,[...e[0]||(e[0]=[c('<h1 id="シーン形式のリソース" tabindex="-1">シーン形式のリソース <a class="header-anchor" href="#シーン形式のリソース" aria-label="Permalink to &quot;シーン形式のリソース&quot;">​</a></h1><p>キャラクターと背景は <code>PackedScene</code> を参照します。シーンには画像、動画、Spine、Live2D、シェーダー、独自ノードを配置できます。</p><p>キャラクターシーンは <code>KonadoCharacterSceneBase</code> を継承し、<code>_apply_status(resolved_status_name, original_status_name)</code> をオーバーライドします。状態名を検証できる場合は <code>_has_status</code> も実装します。遅延トランジションでは要求の受付時と最終適用時に確認されるため、<code>_has_status</code> は副作用がなく冪等でなければなりません。純粋なテクスチャを安全に提供できるシーンは <code>_get_current_status_transition_frame</code> と <code>_get_status_transition_frame</code> の両方を実装し、<code>KonadoCharacterTransitionFrame</code> によるプリマルチプライド Alpha ブレンドを利用できます。副作用のないフレームを提供できない Live2D、Spine、動画、独自シーンは安全なフェードアウト、状態適用、フェードインへ自動的にフォールバックします。どちらの経路もキャラクターシーンを複製しません。設定については<a href="./../script/actor/actor-change-state.html">アクター状態の切り替え</a>を参照してください。舞台アニメーションには <code>KonadoActorMotionLayer</code> を使用します。</p><p>状態フレームの各呼び出しでは新しい独立したフレームを返し、両端で同じ可変フレームを再利用しないでください。</p><p>背景シーンは <code>KonadoBackgroundSceneBase</code> を継承します。カメラ命令を使う場合は、一意な名前の <code>KonadoCameraMarker</code> を追加してください。このノードは目標位置とズームだけを保持し、実際の描画はダイアログテンプレートのカメラが行います。独自の描画用カメラを <code>KonadoCameraMarker</code> に置き換えないでください。組み込みトランジションは <code>KonadoBackgroundTransitionLayer</code> が処理し、デフォルトでは <code>SubViewport</code> でシーン全体をキャプチャします。最終表示が未加工の単一ソーステクスチャと完全に一致する場合に限り <code>DIRECT_TEXTURE</code> を選択できます。レイアウト、変形、カメラ、アニメーション、マテリアル、色調変更、複数の描画ノードを使用する背景では <code>VIEWPORT_CAPTURE</code> を維持してください。</p>',5)])])}const m=a(s,[["render",r]]);export{u as __pageData,m as default};
